/**
 * - consent: off until the person switches it on.
 * - legitimate_interest: on by default, the person may object (switch off).
 * - required: always on, cannot be switched off (the app does not work
 *   without it).
 */
export type LegalBasis = "consent" | "legitimate_interest" | "required";

