export type PurposeChoices = Record<PurposeId, boolean>;
export type PartnerChoices = Record<PartnerId, boolean>;

export type ConsentChoices = {
  purposes: PurposeChoices;
  partners: PartnerChoices;
};

export function partnersFor(surface: Surface): Partner[] {
  return PARTNERS.filter((p) => p.surfaces.includes(surface));
}

/** What the screen shows before anyone touches a switch. */
export function defaultChoices(): ConsentChoices {
  const purposes = {} as PurposeChoices;
  for (const id of PURPOSE_IDS) {
    purposes[id] = PURPOSE_BASIS[id] !== "consent";
  }
  const partners = {} as PartnerChoices;
  for (const p of PARTNERS) {
    // A partner that runs on legitimate interest (every gate purpose is
    // LI/required, e.g. PostHog) starts on, like its purposes. A partner that
    // needs consent to start at all (AppsFlyer, Google Ads) starts off - the
    // same picture as the Didomi partner list Cal AI shows.
    partners[p.id] =
      p.required || p.gate.every((id) => PURPOSE_BASIS[id] !== "consent");
  }
  return { purposes, partners };
}

export function acceptAllChoices(): ConsentChoices {
  const purposes = {} as PurposeChoices;
  for (const id of PURPOSE_IDS) purposes[id] = true;
  const partners = {} as PartnerChoices;
  for (const p of PARTNERS) partners[p.id] = true;
  return { purposes, partners };
}

export function rejectAllChoices(): ConsentChoices {
  const purposes = {} as PurposeChoices;
  for (const id of PURPOSE_IDS) purposes[id] = PURPOSE_BASIS[id] === "required";
  const partners = {} as PartnerChoices;
  for (const p of PARTNERS) partners[p.id] = p.required;
  return { purposes, partners };
}

/**
 * Required purposes and partners are always on, whatever a stale client or a
 * hand-edited request says. Unknown keys are dropped.
 */
export function normalizeChoices(input: {
  purposes?: Partial<Record<string, boolean>>;
  partners?: Partial<Record<string, boolean>>;
}): ConsentChoices {
  const base = rejectAllChoices();
  for (const id of PURPOSE_IDS) {
    if (PURPOSE_BASIS[id] === "required") continue;
    const value = input.purposes?.[id];
    if (typeof value === "boolean") base.purposes[id] = value;
  }
  for (const p of PARTNERS) {
    if (p.required) continue;
    const value = input.partners?.[p.id];
    if (typeof value === "boolean") base.partners[p.id] = value;
  }
  return base;
}

/** A partner's SDK may start only when it is on AND every purpose in its `gate` is on. */
export function partnerAllowed(choices: ConsentChoices, id: PartnerId): boolean {
  const partner = PARTNERS.find((p) => p.id === id);
  if (!partner) return false;
  if (partner.required) return true;
  if (!choices.partners[id]) return false;
  return partner.gate.every((purpose) => choices.purposes[purpose]);
}

/**
 * Whether to show Apple's App Tracking Transparency prompt: only when the
 * person allowed device storage/access and an attribution partner may run.
 */
export function wantsAppleTracking(choices: ConsentChoices): boolean {
  return (
    choices.purposes.store_access &&
    (partnerAllowed(choices, "appsflyer") || partnerAllowed(choices, "google_ads"))
  );
}
